#!/usr/bin/env python3
import json, pathlib
FILES = json.loads('{".gitignore": ".venv/\\n__pycache__/\\n*.pyc\\n.DS_Store\\n.streamlit/secrets.toml\\n", "README.md": "# Multilevel Language Translator (NLP Class Project)\\n\\nA **multilevel** translation system: text passes through clear NLP stages instead of a single black-box \\u201ctranslate\\u201d button.\\n\\n## What \\u201cmultilevel\\u201d means here\\n\\n| Level | Stage | NLP role |\\n|-------|--------|----------|\\n| **1** | Language detection | Identify source language |\\n| **2** | Preprocessing | Clean text, normalize, split sentences |\\n| **3** | Translation | Translate each sentence to the target language |\\n| **4** | Quality check | Back-translate + similarity score (rough quality signal) |\\n\\nThis is useful for a class demo because you can **show each stage** and explain why pipelines matter in real NLP systems.\\n\\n## Tech stack\\n\\n- **UI:** Streamlit\\n- **Detection:** `langdetect`\\n- **Preprocessing:** regex + sentence splitting (`nltk` punkt)\\n- **Translation:** `deep-translator` (Google Translate backend; no GPU required)\\n- **Similarity (Level 4):** SequenceMatcher / optional rapidfuzz\\n\\n## Run locally\\n\\n```bash\\ncd nlp_multilevel_translator\\npython3 -m venv .venv\\nsource .venv/bin/activate\\npip install -r requirements.txt\\npython -m nltk.downloader punkt punkt_tab\\nstreamlit run app.py\\n```\\n\\nOpen the local URL Streamlit prints (usually http://localhost:8501).\\n\\n## Demo script for viva\\n\\n1. Paste English text \\u2192 choose Hindi (or another target).\\n2. Show **Level 1**: detected language.\\n3. Show **Level 2**: cleaned sentences.\\n4. Show **Level 3**: translated output.\\n5. Show **Level 4**: back-translation + similarity %.\\n6. Explain: similarity is only a heuristic, not a perfect BLEU score.\\n\\n## Project layout\\n\\n```\\nnlp_multilevel_translator/\\n  app.py                 # Streamlit UI\\n  pipeline/\\n    detect.py            # Level 1\\n    preprocess.py        # Level 2\\n    translate.py         # Level 3\\n    quality.py           # Level 4\\n  requirements.txt\\n  README.md\\n```\\n\\n## Future upgrades (optional)\\n\\n- Add Hugging Face NLLB / MarianMT for offline neural MT\\n- Add BLEU / chrF evaluation on a small parallel corpus\\n- Add glossary / domain terms (medical, legal)\\n- Export pipeline log as JSON for report screenshots\\n", "app.py": "\\"\\"\\"\\nMultilevel Language Translator \\u2014 Streamlit app (NLP class project)\\n\\nPipeline:\\n  Level 1 Language detection\\n  Level 2 Preprocessing\\n  Level 3 Sentence translation\\n  Level 4 Back-translation quality check\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport streamlit as st\\n\\nfrom pipeline.detect import detect_language\\nfrom pipeline.preprocess import preprocess_text\\nfrom pipeline.translate import SUPPORTED_TARGETS, translate_sentences\\nfrom pipeline.quality import quality_check\\n\\nst.set_page_config(\\n    page_title=\\"Multilevel Language Translator\\",\\n    page_icon=\\"\\ud83c\\udf10\\",\\n    layout=\\"wide\\",\\n)\\n\\nst.title(\\"Multilevel Language Translator\\")\\nst.caption(\\n    \\"NLP class project \\u2014 translation as a **4-level pipeline**, not a single black box.\\"\\n)\\n\\nwith st.sidebar:\\n    st.header(\\"Settings\\")\\n    target_name = st.selectbox(\\"Target language\\", list(SUPPORTED_TARGETS.keys()), index=1)\\n    target_code = SUPPORTED_TARGETS[target_name]\\n    run_quality = st.checkbox(\\"Run Level 4 quality check\\", value=True)\\n    st.markdown(\\"---\\")\\n    st.markdown(\\n        \\"\\"\\"\\n**Levels**\\n1. Detect language  \\n2. Preprocess / split sentences  \\n3. Translate each sentence  \\n4. Back-translate + similarity  \\n\\"\\"\\"\\n    )\\n\\ntext = st.text_area(\\n    \\"Enter text to translate\\",\\n    height=160,\\n    placeholder=\\"Type or paste text in any supported language\\u2026\\",\\n)\\n\\ncol_run, col_clear = st.columns([1, 1])\\nrun = col_run.button(\\"Run multilevel translation\\", type=\\"primary\\")\\nif col_clear.button(\\"Clear\\"):\\n    st.rerun()\\n\\nif run:\\n    if not text.strip():\\n        st.warning(\\"Please enter some text.\\")\\n        st.stop()\\n\\n    # -------- Level 1 --------\\n    st.subheader(\\"Level 1 \\u2014 Language detection\\")\\n    detection = detect_language(text)\\n    if detection.get(\\"error\\"):\\n        st.error(f\\"Detection issue: {detection[\'error\']}\\")\\n    c1, c2, c3 = st.columns(3)\\n    c1.metric(\\"Detected\\", detection.get(\\"name\\", \\"Unknown\\"))\\n    c2.metric(\\"Code\\", detection.get(\\"code\\", \\"\\u2014\\"))\\n    c3.metric(\\"Confidence\\", f\\"{detection.get(\'confidence\', 0) * 100:.1f}%\\")\\n    if detection.get(\\"candidates\\"):\\n        st.write(\\"Top candidates:\\")\\n        st.dataframe(detection[\\"candidates\\"], use_container_width=True, hide_index=True)\\n\\n    # -------- Level 2 --------\\n    st.subheader(\\"Level 2 \\u2014 Preprocessing\\")\\n    prep = preprocess_text(text)\\n    p1, p2, p3 = st.columns(3)\\n    p1.metric(\\"Sentences\\", prep[\\"sentence_count\\"])\\n    p2.metric(\\"Words\\", prep[\\"word_count\\"])\\n    p3.metric(\\"Characters\\", prep[\\"char_count\\"])\\n    st.text_area(\\"Cleaned text\\", prep[\\"cleaned\\"], height=100)\\n    st.write(\\"Sentence units:\\")\\n    for i, s in enumerate(prep[\\"sentences\\"], start=1):\\n        st.markdown(f\\"**{i}.** {s}\\")\\n\\n    # -------- Level 3 --------\\n    st.subheader(f\\"Level 3 \\u2014 Translation \\u2192 {target_name}\\")\\n    source_code = detection.get(\\"code\\")\\n    if source_code in (None, \\"unknown\\"):\\n        source_code = \\"auto\\"\\n    # deep-translator uses zh-CN; langdetect may return zh-cn\\n    if isinstance(source_code, str) and source_code.lower().startswith(\\"zh\\"):\\n        source_code = \\"zh-CN\\"\\n\\n    with st.spinner(\\"Translating sentence by sentence\\u2026\\"):\\n        result = translate_sentences(\\n            prep[\\"sentences\\"],\\n            target_code=target_code,\\n            source_code=source_code,\\n        )\\n\\n    st.success(\\"Translation complete\\")\\n    st.text_area(\\"Translated text\\", result[\\"translated_text\\"], height=140)\\n    st.write(\\"Sentence-level log (good for report screenshots):\\")\\n    st.dataframe(result[\\"rows\\"], use_container_width=True, hide_index=True)\\n\\n    # -------- Level 4 --------\\n    if run_quality and result[\\"translated_text\\"]:\\n        st.subheader(\\"Level 4 \\u2014 Quality check (back-translation)\\")\\n        with st.spinner(\\"Back-translating for similarity check\\u2026\\"):\\n            q = quality_check(\\n                prep[\\"cleaned\\"],\\n                result[\\"translated_text\\"],\\n                source_code=source_code if source_code != \\"auto\\" else detection.get(\\"code\\", \\"en\\"),\\n                target_code=target_code,\\n            )\\n        q1, q2 = st.columns(2)\\n        q1.metric(\\"Similarity\\", f\\"{q.get(\'similarity_pct\', 0)}%\\")\\n        q2.metric(\\"Label\\", q.get(\\"label\\", \\"\\u2014\\"))\\n        st.text_area(\\"Back-translation\\", q.get(\\"back_translation\\", \\"\\"), height=120)\\n        st.info(q.get(\\"note\\", \\"\\"))\\n\\n    st.markdown(\\"---\\")\\n    st.markdown(\\n        \\"**How to explain this in viva:** \\"\\n        \\"Level 1 finds the source language; Level 2 prepares clean sentence units; \\"\\n        \\"Level 3 translates each unit; Level 4 roughly checks meaning preservation \\"\\n        \\"via back-translation. Production MT uses stronger models and formal metrics (BLEU/chrF).\\"\\n    )\\n", "pipeline/__init__.py": "\\"\\"\\"Multilevel translation pipeline.\\"\\"\\"\\n\\nfrom .detect import detect_language\\nfrom .preprocess import preprocess_text\\nfrom .translate import translate_sentences\\nfrom .quality import quality_check\\n\\n__all__ = [\\n    \\"detect_language\\",\\n    \\"preprocess_text\\",\\n    \\"translate_sentences\\",\\n    \\"quality_check\\",\\n]\\n", "pipeline/detect.py": "\\"\\"\\"Level 1 \\u2014 Language detection.\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langdetect import DetectorFactory, detect, detect_langs\\n\\n# Make detection deterministic for demos/reports\\nDetectorFactory.seed = 0\\n\\n# ISO 639-1 \\u2192 display name (common class demo languages)\\nLANG_NAMES = {\\n    \\"en\\": \\"English\\",\\n    \\"hi\\": \\"Hindi\\",\\n    \\"es\\": \\"Spanish\\",\\n    \\"fr\\": \\"French\\",\\n    \\"de\\": \\"German\\",\\n    \\"it\\": \\"Italian\\",\\n    \\"pt\\": \\"Portuguese\\",\\n    \\"ru\\": \\"Russian\\",\\n    \\"ja\\": \\"Japanese\\",\\n    \\"ko\\": \\"Korean\\",\\n    \\"zh-cn\\": \\"Chinese (Simplified)\\",\\n    \\"zh-tw\\": \\"Chinese (Traditional)\\",\\n    \\"ar\\": \\"Arabic\\",\\n    \\"bn\\": \\"Bengali\\",\\n    \\"ta\\": \\"Tamil\\",\\n    \\"te\\": \\"Telugu\\",\\n    \\"mr\\": \\"Marathi\\",\\n    \\"gu\\": \\"Gujarati\\",\\n    \\"pa\\": \\"Punjabi\\",\\n    \\"ur\\": \\"Urdu\\",\\n    \\"tr\\": \\"Turkish\\",\\n    \\"nl\\": \\"Dutch\\",\\n    \\"pl\\": \\"Polish\\",\\n    \\"uk\\": \\"Ukrainian\\",\\n    \\"vi\\": \\"Vietnamese\\",\\n    \\"th\\": \\"Thai\\",\\n    \\"id\\": \\"Indonesian\\",\\n}\\n\\n\\ndef code_to_name(code: str) -> str:\\n    return LANG_NAMES.get(code, code)\\n\\n\\ndef detect_language(text: str) -> dict:\\n    \\"\\"\\"\\n    Detect source language.\\n\\n    Returns:\\n        {\\n          \\"code\\": \\"en\\",\\n          \\"name\\": \\"English\\",\\n          \\"confidence\\": 0.99,\\n          \\"candidates\\": [{\\"code\\": \\"...\\", \\"prob\\": 0.9}, ...]\\n        }\\n    \\"\\"\\"\\n    text = (text or \\"\\").strip()\\n    if not text:\\n        return {\\n            \\"code\\": \\"unknown\\",\\n            \\"name\\": \\"Unknown\\",\\n            \\"confidence\\": 0.0,\\n            \\"candidates\\": [],\\n            \\"error\\": \\"Empty text\\",\\n        }\\n\\n    try:\\n        code = detect(text)\\n        langs = detect_langs(text)\\n        candidates = [\\n            {\\"code\\": str(x.lang), \\"name\\": code_to_name(str(x.lang)), \\"prob\\": float(x.prob)}\\n            for x in langs[:5]\\n        ]\\n        confidence = float(langs[0].prob) if langs else 0.0\\n        return {\\n            \\"code\\": code,\\n            \\"name\\": code_to_name(code),\\n            \\"confidence\\": confidence,\\n            \\"candidates\\": candidates,\\n        }\\n    except Exception as exc:  # noqa: BLE001 \\u2014 surface to UI for demo clarity\\n        return {\\n            \\"code\\": \\"unknown\\",\\n            \\"name\\": \\"Unknown\\",\\n            \\"confidence\\": 0.0,\\n            \\"candidates\\": [],\\n            \\"error\\": str(exc),\\n        }\\n", "pipeline/preprocess.py": "\\"\\"\\"Level 2 \\u2014 Text preprocessing.\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\nfrom typing import List\\n\\n_SENT_SPLIT = re.compile(r\\"(?<=[.!?\\u0964\\u061f])\\\\s+\\")\\n\\n\\ndef _ensure_nltk_punkt() -> None:\\n    try:\\n        import nltk\\n        from nltk.tokenize import sent_tokenize\\n\\n        # Probe once; download if missing\\n        try:\\n            sent_tokenize(\\"Test. Sentence.\\")\\n        except LookupError:\\n            nltk.download(\\"punkt\\", quiet=True)\\n            nltk.download(\\"punkt_tab\\", quiet=True)\\n    except Exception:\\n        pass\\n\\n\\ndef clean_text(text: str) -> str:\\n    \\"\\"\\"Normalize whitespace and strip noisy characters for translation.\\"\\"\\"\\n    text = text.replace(\\"\\\\u00a0\\", \\" \\")\\n    text = re.sub(r\\"[\\\\t\\\\r]+\\", \\" \\", text)\\n    text = re.sub(r\\"\\\\n{3,}\\", \\"\\\\n\\\\n\\", text)\\n    text = re.sub(r\\"[ ]{2,}\\", \\" \\", text)\\n    return text.strip()\\n\\n\\ndef split_sentences(text: str) -> List[str]:\\n    \\"\\"\\"Split into sentences (NLTK if available, else regex fallback).\\"\\"\\"\\n    text = clean_text(text)\\n    if not text:\\n        return []\\n\\n    _ensure_nltk_punkt()\\n    try:\\n        from nltk.tokenize import sent_tokenize\\n\\n        parts = [p.strip() for p in sent_tokenize(text) if p.strip()]\\n        if parts:\\n            return parts\\n    except Exception:\\n        pass\\n\\n    parts = [p.strip() for p in _SENT_SPLIT.split(text) if p.strip()]\\n    return parts or [text]\\n\\n\\ndef preprocess_text(text: str) -> dict:\\n    \\"\\"\\"\\n    Level 2 output for the UI / report.\\n\\n    Returns cleaned text + sentence list + light stats.\\n    \\"\\"\\"\\n    cleaned = clean_text(text or \\"\\")\\n    sentences = split_sentences(cleaned)\\n    words = re.findall(r\\"\\\\w+\\", cleaned, flags=re.UNICODE)\\n    return {\\n        \\"original\\": text or \\"\\",\\n        \\"cleaned\\": cleaned,\\n        \\"sentences\\": sentences,\\n        \\"sentence_count\\": len(sentences),\\n        \\"word_count\\": len(words),\\n        \\"char_count\\": len(cleaned),\\n    }\\n", "pipeline/quality.py": "\\"\\"\\"Level 4 \\u2014 Quality check via back-translation + similarity.\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom difflib import SequenceMatcher\\n\\ntry:\\n    from rapidfuzz import fuzz\\n\\n    def _ratio(a: str, b: str) -> float:\\n        return float(fuzz.token_sort_ratio(a, b)) / 100.0\\n\\nexcept ImportError:  # pragma: no cover\\n\\n    def _ratio(a: str, b: str) -> float:\\n        return SequenceMatcher(None, a.lower(), b.lower()).ratio()\\n\\n\\ndef similarity(a: str, b: str) -> float:\\n    \\"\\"\\"Return similarity in [0, 1].\\"\\"\\"\\n    a = (a or \\"\\").strip()\\n    b = (b or \\"\\").strip()\\n    if not a or not b:\\n        return 0.0\\n    return _ratio(a, b)\\n\\n\\ndef quality_label(score: float) -> str:\\n    if score >= 0.75:\\n        return \\"Good (heuristic)\\"\\n    if score >= 0.50:\\n        return \\"Okay (heuristic)\\"\\n    return \\"Weak (heuristic)\\"\\n\\n\\ndef quality_check(\\n    original: str,\\n    translated: str,\\n    *,\\n    source_code: str,\\n    target_code: str,\\n) -> dict:\\n    \\"\\"\\"\\n    Back-translate target \\u2192 source and compare with original.\\n\\n    Classroom heuristic \\u2014 not a formal MT metric like BLEU.\\n    \\"\\"\\"\\n    from .translate import translate_one\\n\\n    original = (original or \\"\\").strip()\\n    translated = (translated or \\"\\").strip()\\n    if not original or not translated:\\n        return {\\n            \\"back_translation\\": \\"\\",\\n            \\"similarity\\": 0.0,\\n            \\"similarity_pct\\": 0.0,\\n            \\"label\\": \\"N/A\\",\\n            \\"note\\": \\"Need both original and translated text.\\",\\n        }\\n\\n    back_target = source_code\\n    if not back_target or back_target in (\\"unknown\\", \\"auto\\"):\\n        back_target = \\"en\\"\\n\\n    # Normalize Chinese codes for GoogleTranslator\\n    if back_target.lower().startswith(\\"zh\\"):\\n        back_target = \\"zh-CN\\"\\n    if target_code.lower().startswith(\\"zh\\"):\\n        target_code = \\"zh-CN\\"\\n\\n    try:\\n        back = translate_one(translated, source=target_code, target=back_target)\\n    except Exception as exc:  # noqa: BLE001\\n        return {\\n            \\"back_translation\\": \\"\\",\\n            \\"similarity\\": 0.0,\\n            \\"similarity_pct\\": 0.0,\\n            \\"label\\": \\"Error\\",\\n            \\"note\\": str(exc),\\n        }\\n\\n    score = similarity(original, back)\\n    return {\\n        \\"back_translation\\": back,\\n        \\"similarity\\": round(score, 4),\\n        \\"similarity_pct\\": round(score * 100, 1),\\n        \\"label\\": quality_label(score),\\n        \\"note\\": (\\n            \\"Back-translation similarity is a rough classroom check. \\"\\n            \\"Real evaluation uses BLEU/chrF on parallel corpora.\\"\\n        ),\\n    }\\n", "pipeline/translate.py": "\\"\\"\\"Level 3 \\u2014 Sentence-level translation.\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import List, Optional\\n\\nfrom deep_translator import GoogleTranslator\\n\\n# UI-friendly language list (deep-translator Google codes)\\nSUPPORTED_TARGETS = {\\n    \\"English\\": \\"en\\",\\n    \\"Hindi\\": \\"hi\\",\\n    \\"Spanish\\": \\"es\\",\\n    \\"French\\": \\"fr\\",\\n    \\"German\\": \\"de\\",\\n    \\"Italian\\": \\"it\\",\\n    \\"Portuguese\\": \\"pt\\",\\n    \\"Russian\\": \\"ru\\",\\n    \\"Japanese\\": \\"ja\\",\\n    \\"Korean\\": \\"ko\\",\\n    \\"Chinese (Simplified)\\": \\"zh-CN\\",\\n    \\"Arabic\\": \\"ar\\",\\n    \\"Bengali\\": \\"bn\\",\\n    \\"Tamil\\": \\"ta\\",\\n    \\"Telugu\\": \\"te\\",\\n    \\"Marathi\\": \\"mr\\",\\n    \\"Gujarati\\": \\"gu\\",\\n    \\"Punjabi\\": \\"pa\\",\\n    \\"Urdu\\": \\"ur\\",\\n    \\"Turkish\\": \\"tr\\",\\n    \\"Dutch\\": \\"nl\\",\\n    \\"Vietnamese\\": \\"vi\\",\\n    \\"Thai\\": \\"th\\",\\n    \\"Indonesian\\": \\"id\\",\\n}\\n\\n\\ndef translate_one(text: str, source: str, target: str) -> str:\\n    \\"\\"\\"Translate a single string. source/target are ISO-ish codes (or \'auto\').\\"\\"\\"\\n    text = (text or \\"\\").strip()\\n    if not text:\\n        return \\"\\"\\n    translator = GoogleTranslator(source=source, target=target)\\n    return translator.translate(text) or \\"\\"\\n\\n\\ndef translate_sentences(\\n    sentences: List[str],\\n    target_code: str,\\n    source_code: Optional[str] = None,\\n) -> dict:\\n    \\"\\"\\"\\n    Translate sentence by sentence (multilevel: unit = sentence).\\n\\n    source_code=None \\u2192 auto-detect at translator level.\\n    \\"\\"\\"\\n    source = source_code or \\"auto\\"\\n    rows = []\\n    outputs = []\\n\\n    for i, sent in enumerate(sentences, start=1):\\n        try:\\n            out = translate_one(sent, source=source, target=target_code)\\n            err = None\\n        except Exception as exc:  # noqa: BLE001\\n            out = \\"\\"\\n            err = str(exc)\\n        rows.append(\\n            {\\n                \\"index\\": i,\\n                \\"source\\": sent,\\n                \\"translation\\": out,\\n                \\"error\\": err,\\n            }\\n        )\\n        if out:\\n            outputs.append(out)\\n\\n    return {\\n        \\"source_code\\": source,\\n        \\"target_code\\": target_code,\\n        \\"rows\\": rows,\\n        \\"translated_text\\": \\" \\".join(outputs).strip(),\\n    }\\n", "requirements.txt": "streamlit>=1.28.0\\nlangdetect>=1.0.9\\ndeep-translator>=1.11.4\\nnltk>=3.8.1\\nrapidfuzz>=3.0.0\\n"}')
dest = pathlib.Path.home() / 'Multilevel_Language_Translator'
print('Creating', dest)
for rel, content in FILES.items():
    path = dest / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')
    print(' wrote', path)
print('\nDONE. Next:')
print('  cd ~/Multilevel_Language_Translator')
print('  python3 -m venv .venv')
print('  source .venv/bin/activate')
print('  pip install -r requirements.txt')
print('  streamlit run app.py')
